--
-- Table structure for table `wf_subflow_request`
--

DROP TABLE IF EXISTS `wf_subflow_request`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wf_subflow_request` (
  `id` bigint NOT NULL COMMENT '主键（雪花 ID）',
  `tenant_id` varchar(12) NOT NULL DEFAULT '000000' COMMENT '租户',
  `main_inst_id` bigint NOT NULL COMMENT '主流程实例 ID',
  `sub_inst_id` bigint NOT NULL COMMENT '子流程实例 ID（唯一）',
  `sub_def_id` bigint DEFAULT NULL COMMENT '子流程定义 ID',
  `main_node_key` varchar(64) DEFAULT NULL COMMENT '触发子流程的主流程节点 Key',
  `is_same` tinyint NOT NULL DEFAULT '1' COMMENT '是否「相同子流程」范围（1=是 0=否）',
  `all_end_before_submit` tinyint NOT NULL DEFAULT '0' COMMENT '快照：全部归档才能提交（阻塞主流程归档）',
  `data_summary` tinyint NOT NULL DEFAULT '0' COMMENT '快照：子流程归档后汇总数据到主流程',
  `auto_forward` tinyint NOT NULL DEFAULT '0' COMMENT '快照：全部归档后自动流转主流程',
  `remind_enabled` tinyint NOT NULL DEFAULT '0' COMMENT '快照：全部归档后提醒',
  `remind_types` varchar(32) DEFAULT NULL COMMENT '提醒方式：含 sys=流程提醒 ml=短信 sm=邮件',
  `remind_before_operator` tinyint NOT NULL DEFAULT '0' COMMENT '提醒对象：节点操作者本人',
  `remind_persons` varchar(255) DEFAULT NULL COMMENT '提醒对象：指定人员（人力资源 ID 逗号分隔）',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0=进行中（未归档） 1=已归档',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `archive_time` datetime DEFAULT NULL COMMENT '子流程归档时间',
  `create_user` bigint DEFAULT NULL COMMENT '创建人',
  `create_dept` bigint DEFAULT NULL COMMENT '创建部门',
  `update_user` bigint DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `is_deleted` int NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_subflow_sub_inst` (`sub_inst_id`),
  KEY `idx_subflow_main_node_status` (`main_inst_id`,`main_node_key`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='主/子流程请求关系表（子流程高级设置）';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `wf_subflow_request`
--

LOCK TABLES `wf_subflow_request` WRITE;
/*!40000 ALTER TABLE `wf_subflow_request` DISABLE KEYS */;
/*!40000 ALTER TABLE `wf_subflow_request` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `wf_task`
--

DROP TABLE IF EXISTS `wf_task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wf_task` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `inst_id` bigint unsigned NOT NULL COMMENT '流程实例ID',
  `engine_task_id` varchar(64) NOT NULL DEFAULT '' COMMENT '引擎任务ID（Flowable），弱关联',
  `node_key` varchar(64) NOT NULL COMMENT '节点Key',
  `assignee` bigint NOT NULL COMMENT '办理人',
  `original_user` bigint DEFAULT NULL COMMENT '代理人代办时的原处理人',
  `sign_order` tinyint NOT NULL DEFAULT '0' COMMENT '会签关系',
  `receive_time` datetime DEFAULT NULL COMMENT '接收时间',
  `operate_time` datetime DEFAULT NULL COMMENT '处理时间',
  `view_time` datetime DEFAULT NULL COMMENT '首次查看时间（流程轨迹「已查看」判定）',
  `due_time` datetime DEFAULT NULL COMMENT '截止时间',
  `tenant_id` varchar(32) NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `create_user` bigint DEFAULT NULL COMMENT '创建人',
  `create_dept` bigint DEFAULT NULL COMMENT '创建部门',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user` bigint DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
